<script setup lang="ts">
import { ref } from 'vue';import { CefEvent,type DocumentView,type VehicleDocumentView } from '@eclipse/shared';import { onClient,toClient } from '../core/bridge';
const visible=ref(false),kind=ref<'passport'|'vehicle'>('passport'),data=ref<DocumentView|VehicleDocumentView|null>(null);
onClient(CefEvent.DocumentPresentation,p=>{const s=(p??{}) as {visible?:boolean;kind?:'passport'|'vehicle';data?:DocumentView|VehicleDocumentView};visible.value=s.visible===true;kind.value=s.kind??'passport';data.value=s.data??null;});
const close=()=>{visible.value=false;toClient(CefEvent.ContextAction,{id:'close'});};
const passport=()=>data.value as DocumentView;const vehicle=()=>data.value as VehicleDocumentView;
</script>
<template><Transition name="doc"><div v-if="visible&&data" class="shade e-interactive" @click.self="close"><article class="card"><header><div><small>ECLIPSE RP · OFFICIAL DOCUMENT</small><h2>{{kind==='passport'?'Паспорт гражданина':'Свидетельство о регистрации ТС'}}</h2></div><button @click="close">×</button></header><template v-if="kind==='passport'"><div class="number">{{passport().passportNumber}}</div><dl><div><dt>Static ID</dt><dd>#{{passport().characterId}}</dd></div><div><dt>Выдан</dt><dd>{{new Date(passport().issuedAt).toLocaleDateString('ru-RU')}}</dd></div><div v-for="(v,k) in passport().licenses" :key="k"><dt>Лицензия · {{k}}</dt><dd>{{v?new Date(v).toLocaleDateString('ru-RU'):'Бессрочно / активна'}}</dd></div></dl></template><template v-else><div class="number">VIN {{vehicle().vin}}</div><dl><div><dt>Модель</dt><dd>{{vehicle().model}}</dd></div><div><dt>Гос. номер</dt><dd>{{vehicle().plate||'Не зарегистрирован'}}</dd></div><div><dt>Страховка</dt><dd>{{vehicle().insuranceUntil?new Date(vehicle().insuranceUntil!).toLocaleDateString('ru-RU'):'Нет'}}</dd></div></dl></template><footer>Документ показан находящимся рядом игроком · данные получены с сервера</footer></article></div></Transition></template>
<style scoped>.shade{position:fixed;inset:0;display:grid;place-items:center;background:#03060b88;backdrop-filter:blur(7px)}.card{width:440px;padding:22px;border:1px solid var(--e-border);border-radius:22px;background:linear-gradient(145deg,rgba(20,25,35,.99),rgba(8,11,17,.99));box-shadow:0 28px 80px #0009;color:#fff}.card header{display:flex;justify-content:space-between;align-items:flex-start}.card h2{margin:5px 0 0;font-size:20px}.card small,dt,footer{color:var(--e-text-muted);font-size:10px}.card button{border:0;background:transparent;color:#fff;font-size:24px;cursor:pointer}.number{margin:24px 0;padding:14px;border-radius:13px;background:var(--e-surface-2);font-weight:800;letter-spacing:.08em}dl{display:grid;gap:10px;margin:0}dl div{display:flex;justify-content:space-between;gap:20px;padding-bottom:9px;border-bottom:1px solid var(--e-border)}dd{margin:0;text-align:right}footer{margin-top:20px;line-height:1.5}.doc-enter-active,.doc-leave-active{transition:.18s}.doc-enter-from,.doc-leave-to{opacity:0;transform:scale(.98)}</style>